package org.example;
import com.itextpdf.kernel.pdf.*;import org.example.config.ConfigManager;import org.example.database.DatabaseManager;import org.example.service.InvoicePdfService;import java.nio.file.*;import java.sql.*;
public final class RefundPdfSmoke{public static void main(String[]a)throws Exception{ConfigManager.load();DatabaseManager.initialize();int sales=0,purchase=0;try(Connection c=DatabaseManager.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT return_no,return_type FROM return_register ORDER BY id")){while(r.next()){boolean isSales=r.getString(2).toUpperCase().startsWith("SALES");Path p=InvoicePdfService.refund(r.getString(1),isSales);try(PdfReader reader=new PdfReader(p.toFile());PdfDocument pdf=new PdfDocument(reader)){if(pdf.getNumberOfPages()<1)throw new IllegalStateException("Empty refund PDF: "+r.getString(1));}if(isSales)sales++;else purchase++;}}System.out.println("REFUND_PDF_OK sales="+sales+" purchases="+purchase);}}
